}
#big-picture .souvenir-lightbox__meta-separator {
  width: 4px;
  height: 4px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--text-secondary);
  opacity: 0.7;
}
#big-picture .souvenir-lightbox__unlock-time {
  opacity: 0.65;
}
#big-picture .souvenir-lightbox__game {
  gap: var(--spacing-unit);
}
#big-picture .souvenir-lightbox__game-icon {
  position: relative;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  overflow: hidden;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
}
#big-picture .souvenir-lightbox__game-icon img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
#big-picture .souvenir-lightbox__rarity {
  flex-shrink: 0;
  gap: calc(var(--spacing-unit) / 2);
  padding: calc(var(--spacing-unit) * 0.75) var(--spacing-unit);
  border: 1px solid transparent;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
}
#big-picture .souvenir-lightbox__rarity--rare {
  border-color: rgba(244, 165, 16, 0.65);
  background: rgba(48, 32, 4, 0.88);
  color: #ffd36d;
}
#big-picture .souvenir-lightbox__rarity--platinum {
  border-color: rgba(12, 241, 202, 0.7);
  background: linear-gradient(105deg, transparent 70%, rgba(255, 255, 255, 0.15) 85%, transparent 100%), linear-gradient(120deg, #30edc5 0%, #16b195 100%);
  color: #052d26;
}
#big-picture .souvenir-lightbox__actions {
  flex-shrink: 0;
  justify-content: flex-end;
  gap: var(--spacing-unit);
}
#big-picture .souvenir-lightbox__actions .button__icon-container::before,
#big-picture .souvenir-lightbox__actions .button__icon-container::after {
  display: none;
}
#big-picture .souvenir-lightbox__action--pending.button--disabled {
  opacity: 1;
}
@media (max-width: 1100px) {
  #big-picture .souvenir-lightbox__info {
    align-items: stretch;
    flex-direction: column;
  }
  #big-picture .souvenir-lightbox__actions {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}#big-picture .big-picture-souvenir-report-modal {
  width: min(560px, 100vw - 64px);
}
#big-picture .big-picture-souvenir-report-modal__backdrop {
  z-index: 130;
}
#big-picture .big-picture-souvenir-report-modal__form {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing-unit) * 4);
}
#big-picture .big-picture-souvenir-report-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: calc(var(--spacing-unit) * 2);
  margin-top: calc(var(--spacing-unit) * 2);
}

