  text-align: center;
  font-size: 16px;
  font-style: normal;
  font-weight: 700;
  line-height: normal;
}

#big-picture .header__search {
  display: flex;
  align-items: center;
  padding: calc(var(--spacing-unit) * 7) calc(var(--spacing-unit) * 6);
  transition: background-color 0.2s ease-in-out;
  cursor: pointer;
  position: relative;
  flex: 1;
}
#big-picture .header__search-trigger {
  position: absolute;
  inset: 0;
  z-index: 2;
  cursor: pointer;
  outline: none;
}
#big-picture .header__search-icon {
  position: absolute;
  z-index: 1;
  pointer-events: none;
}
#big-picture .header__search-icon--left {
  left: calc(var(--spacing-unit) * 6);
}
#big-picture .header__search-icon--right {
  right: calc(var(--spacing-unit) * 6);
}
#big-picture .header__search:hover:not(.header__search--open) {
  background-color: rgba(14, 14, 14, 0.8);
}
#big-picture .header__search:hover:not(.header__search--open) .header__search-icon {
  opacity: 0.8;
}
#big-picture .header__search--open {
  background-color: var(--surface);
  box-shadow: 0 8px 24px 0 rgba(0, 0, 0, 0.6);
}
#big-picture .header__search--open .header__search-trigger {
  pointer-events: none;
}
#big-picture .header__search--open .header__search-input {
  width: 100%;
  opacity: 1;
}
#big-picture .header__search:has(.header__search-trigger:focus-visible), #big-picture .header__search:has(.header__search-trigger[data-focus-visible]) {
  outline: 2px solid var(--secondary-border);
  outline-offset: 2px;
}

#big-picture .header__search-input {
  height: 100%;
  width: 0;
  border: none;
  outline: none;
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  padding: 0 calc(var(--spacing-unit) * 6);
  padding-left: 72px;
  font-size: 16px;
  font-weight: 500;
  background: transparent;
  color: var(--primary);
  opacity: 0;
  transition: all 0.2s ease-in-out;
}
#big-picture .header__search-input::placeholder {
  color: rgba(255, 255, 255, 0.5);
  opacity: 0;
  transition: all 0.2s ease-in-out;
}
#big-picture .header__search--open .header__search-input::placeholder {
  opacity: 1;
}
#big-picture .header__search--open.header__search--closing .header__search-input::placeholder {
  opacity: 0;
  transform: translateX(24px);
