#big-picture {
  --font-space-grotesk: "Space Grotesk";
  --primary: rgba(255, 255, 255, 1);
  --secondary: rgba(20, 20, 20, 1);
  --tertiary: rgba(185, 2, 2, 1);
  --success: rgba(138, 235, 19, 1);
  --alert: rgba(243, 198, 17, 1);
  --error: rgba(225, 29, 72, 1);
  --sucess-secondary: rgba(138, 235, 19, 0.5);
  --alert-secondary: rgba(243, 198, 17, 0.5);
  --error-secondary: rgba(225, 29, 72, 0.5);
  --sucess-background: rgba(138, 235, 19, 0.05);
  --alert-background: rgba(243, 198, 17, 0.05);
  --error-background: rgba(225, 29, 72, 0.05);
  --background: rgba(8, 8, 8, 1);
  --surface: rgba(14, 14, 14, 1);
  --text: rgba(206, 206, 206, 1);
  --text-secondary: rgba(131, 131, 131, 1);
  --text-error: rgba(225, 29, 72, 1);
  --border: rgba(8, 8, 8, 0.1);
  --secondary-border: rgba(255, 255, 255, 0.1);
  --tertiary-border: rgba(185, 2, 2, 0.1);
  --error-border: rgba(225, 29, 72, 0.1);
  --primary-hover: rgba(255, 255, 255, 0.8);
  --secondary-hover: rgba(255, 255, 255, 0.15);
  --tertiary-hover: rgba(185, 2, 2, 0.5);
  --error-hover: rgba(225, 29, 72, 0.2);
  --spacing-unit: 0.25rem;
  --big-picture-header-height: 56px;
}
#big-picture * {
  box-sizing: border-box;
}
#big-picture,
#big-picture,
#big-picture {
  width: 100%;
  height: 100%;
}
#big-picture {
  margin: 0;
  overflow: hidden;
}
#big-picture {
  width: 100%;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  font-family: var(--font-space-grotesk), sans-serif;
}
#big-picture,
#big-picture * {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
#big-picture::-webkit-scrollbar,
#big-picture *::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}
#big-picture .big-picture__app {
  position: relative;
  display: flex;
  flex: 1 1 0;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
#big-picture .big-picture__layout {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1 1 0;
  width: auto;
  min-width: 0;
  min-height: 0;
  overflow: visible;
}
#big-picture .big-picture__content {
  flex: 1 1 0;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding-top: var(--big-picture-header-height);
  box-sizing: border-box;
}
#big-picture h1,
#big-picture h2,
#big-picture h3,
#big-picture h4,
#big-picture h5,
#big-picture h6,
#big-picture p {
  margin: 0;
}
#big-picture button {
  padding: 0;
  background-color: transparent;
  border: none;
  font-family: inherit;
  color: inherit;
}
#big-picture a {
  color: inherit;
  text-decoration: none;
}
#big-picture input {
  font-family: inherit;
  color: inherit;
}
#big-picture ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
#big-picture li {
  margin: 0;
  padding: 0;
}
#big-picture [data-bp-input-mode=mouse] [data-focused=true] {
  outline: none !important;
  box-shadow: none !important;
}#big-picture .catalogue-results-page {
  margin-top: calc(-1 * var(--big-picture-header-height));
  width: 100%;
  min-width: 0;
  height: calc(100% + var(--big-picture-header-height));
  min-height: calc(100% + var(--big-picture-header-height));
  overflow-y: auto;
  overflow-x: hidden;
  background: var(--background);
  color: var(--text);
}

#big-picture .catalogue-container {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing-unit) * 8);
  padding: calc(var(--spacing-unit) * 8) calc(var(--spacing-unit) * 16);
  margin-top: calc(var(--spacing-unit) * 18);
  min-height: fit-content;
}

#big-picture .catalogue-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--spacing-unit) * 8);
}
#big-picture .catalogue-header__summary {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: calc(var(--spacing-unit) * 2);
  min-width: 0;
}
#big-picture .catalogue-header__search-term-text {
  color: rgba(255, 255, 255, 0.8);
  font-size: 18px;
  font-style: normal;
  font-weight: 500;
  line-height: normal;
}
#big-picture .catalogue-header__filters {
  position: relative;
  min-width: 0;
}
#big-picture .catalogue-header__filters-container {
  display: flex;
  flex-direction: row;
  gap: calc(var(--spacing-unit) * 2);
  flex-wrap: wrap;
  align-items: flex-start;
  min-width: 0;
}
#big-picture .catalogue-header__filters-measurements {
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: calc(var(--spacing-unit) * 2);
  width: max-content;
  height: 0;
  overflow: hidden;
  visibility: hidden;
  pointer-events: none;
}
#big-picture .catalogue-header__filters__clear-button {
  border: none;
  margin: 0;
  padding: calc(var(--spacing-unit) * 2);
  background: transparent;
  border-radius: calc(var(--spacing-unit) * 2);
  color: inherit;
  font: inherit;
  transition: opacity 0.2s ease-in-out;
  cursor: pointer;
  appearance: none;
}
#big-picture .catalogue-header__filters__clear-button:hover {
  opacity: 0.8;
}
#big-picture .catalogue-header__filters__clear-button:focus-visible {
  outline: none;
}
#big-picture .catalogue-header__filters__clear-button[data-focus-visible=true] {
  outline: 1px solid var(--primary);
  outline-offset: 2px;
}
#big-picture .catalogue-header__filters__clear-button-text {
  text-decoration: underline;
  text-underline-offset: 2px;
}
#big-picture .catalogue-header__actions {
  display: flex;
  align-items: center;
  flex: none;
  gap: calc(var(--spacing-unit) * 3);
}
#big-picture .catalogue-header__mode-tabs {
  flex: none;
  width: auto;
  min-width: 0;
}
#big-picture .catalogue-header__mode-tabs.tabs {
  width: auto;
  flex: 0 0 auto;
}
#big-picture .catalogue-header__mode-tabs .tabs__content {
  width: auto;
  justify-content: flex-start;
  padding: 0;
  gap: 0;
}
#big-picture .catalogue-header__mode-tabs .tabs__list {
  width: auto;
  flex: 0 0 auto;
}
#big-picture .catalogue-header__mode-tabs .tabs__tablist {
  width: auto;
  flex: 0 0 auto;
  display: inline-flex;
  justify-content: flex-start;
}
#big-picture .catalogue-header__mode-tabs .tabs__tab {
  min-width: 0;
  flex: 0 0 auto;
}
#big-picture .catalogue-header__mode-tab-content {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--spacing-unit) * 2);
  min-width: 0;
}
#big-picture .catalogue-header__mode-tab-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
#big-picture .catalogue-header__mode-tab-icon--classics {
  filter: saturate(1) brightness(1);
}
#big-picture .catalogue-header__filters-button {
  height: 44px;
  padding: 0 calc(var(--spacing-unit) * 4);
  border-radius: calc(var(--spacing-unit) * 2);
  border: 1px solid var(--secondary-border);
  background-color: var(--background);
  color: var(--text);
  gap: calc(var(--spacing-unit) * 2);
  font-size: 14px;
  line-height: 16.59px;
  transition: border-color 0.2s ease-in-out, background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, color 0.2s ease-in-out;
}
#big-picture .catalogue-header__filters-button:hover {
  border-color: var(--secondary-hover);
  background-color: color-mix(in srgb, var(--primary) 2%, var(--background));
}
#big-picture .catalogue-header__filters-button:focus-visible, #big-picture .catalogue-header__filters-button[data-focus-visible=true] {
  outline: none;
  border-color: color-mix(in srgb, var(--primary) 45%, var(--secondary-border));
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--primary) 35%, transparent);
}
#big-picture .catalogue-header__filters-button .button__icon-container {
  color: var(--text-secondary);
  padding: 0;
}
#big-picture .catalogue-header__filters-button .button__icon-container::after, #big-picture .catalogue-header__filters-button .button__icon-container::before {
  display: none;
}
#big-picture .catalogue-header__filters-button .button__text {
  padding: 0;
}
#big-picture .catalogue-header__sort {
  flex: none;
  width: 260px;
}
#big-picture .catalogue-header__sort-select {
  width: 100%;
}
@media (max-width: 767px) {
  #big-picture .catalogue-header {
