#big-picture {
  --font-space-grotesk: "Space Grotesk";
  --primary: rgba(255, 255, 255, 1);
  --secondary: rgba(20, 20, 20, 1);
  --tertiary: rgba(185, 2, 2, 1);
  --success: rgba(138, 235, 19, 1);
  --alert: rgba(243, 198, 17, 1);
  --error: rgba(225, 29, 72, 1);
  --sucess-secondary: rgba(138, 235, 19, 0.5);
  --alert-secondary: rgba(243, 198, 17, 0.5);
  --error-secondary: rgba(225, 29, 72, 0.5);
  --sucess-background: rgba(138, 235, 19, 0.05);
  --alert-background: rgba(243, 198, 17, 0.05);
  --error-background: rgba(225, 29, 72, 0.05);
  --background: rgba(8, 8, 8, 1);
  --surface: rgba(14, 14, 14, 1);
  --text: rgba(206, 206, 206, 1);
  --text-secondary: rgba(131, 131, 131, 1);
  --text-error: rgba(225, 29, 72, 1);
  --border: rgba(8, 8, 8, 0.1);
  --secondary-border: rgba(255, 255, 255, 0.1);
  --tertiary-border: rgba(185, 2, 2, 0.1);
  --error-border: rgba(225, 29, 72, 0.1);
  --primary-hover: rgba(255, 255, 255, 0.8);
  --secondary-hover: rgba(255, 255, 255, 0.15);
  --tertiary-hover: rgba(185, 2, 2, 0.5);
  --error-hover: rgba(225, 29, 72, 0.2);
  --spacing-unit: 0.25rem;
  --big-picture-header-height: 56px;
}
#big-picture * {
  box-sizing: border-box;
}
#big-picture,
#big-picture,
#big-picture {
  width: 100%;
  height: 100%;
}
#big-picture {
  margin: 0;
  overflow: hidden;
}
#big-picture {
  width: 100%;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  font-family: var(--font-space-grotesk), sans-serif;
}
#big-picture,
#big-picture * {
  scrollbar-width: none;
  -ms-overflow-style: none;
}
#big-picture::-webkit-scrollbar,
#big-picture *::-webkit-scrollbar {
  width: 0;
  height: 0;
  display: none;
}
#big-picture .big-picture__app {
  position: relative;
  display: flex;
  flex: 1 1 0;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
#big-picture .big-picture__layout {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1 1 0;
  width: auto;
  min-width: 0;
  min-height: 0;
  overflow: visible;
}
#big-picture .big-picture__content {
  flex: 1 1 0;
  width: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  padding-top: var(--big-picture-header-height);
  box-sizing: border-box;
}
#big-picture h1,
#big-picture h2,
#big-picture h3,
#big-picture h4,
#big-picture h5,
#big-picture h6,
#big-picture p {
  margin: 0;
}
#big-picture button {
  padding: 0;
  background-color: transparent;
  border: none;
  font-family: inherit;
  color: inherit;
}
#big-picture a {
  color: inherit;
  text-decoration: none;
}
#big-picture input {
  font-family: inherit;
  color: inherit;
}
#big-picture ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
#big-picture li {
  margin: 0;
  padding: 0;
}
#big-picture [data-bp-input-mode=mouse] [data-focused=true] {
  outline: none !important;
  box-shadow: none !important;
}#big-picture .catalogue-results-page {
