  flex: 0 0 auto;
  display: inline-flex;
  justify-content: flex-start;
}
#big-picture .catalogue-header__mode-tabs .tabs__tab {
  min-width: 0;
  flex: 0 0 auto;
}
#big-picture .catalogue-header__mode-tab-content {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--spacing-unit) * 2);
  min-width: 0;
}
#big-picture .catalogue-header__mode-tab-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
