  filter: saturate(1) brightness(1);
}
#big-picture .catalogue-header__filters-button {
  height: 44px;
  padding: 0 calc(var(--spacing-unit) * 4);
  border-radius: calc(var(--spacing-unit) * 2);
  border: 1px solid var(--secondary-border);
  background-color: var(--background);
  color: var(--text);
  gap: calc(var(--spacing-unit) * 2);
  font-size: 14px;
  line-height: 16.59px;
  transition: border-color 0.2s ease-in-out, background-color 0.2s ease-in-out, box-shadow 0.2s ease-in-out, color 0.2s ease-in-out;
}
#big-picture .catalogue-header__filters-button:hover {
  border-color: var(--secondary-hover);
  background-color: color-mix(in srgb, var(--primary) 2%, var(--background));
}
#big-picture .catalogue-header__filters-button:focus-visible, #big-picture .catalogue-header__filters-button[data-focus-visible=true] {
  outline: none;
  border-color: color-mix(in srgb, var(--primary) 45%, var(--secondary-border));
