}
#big-picture .souvenir-lightbox__achievement-list-copy strong {
  color: var(--text);
  font-size: 14px;
}
#big-picture .souvenir-lightbox__achievement-list-copy small {
  color: var(--text-secondary);
  font-size: 12px;
}
#big-picture .souvenir-lightbox__meta {
  flex-wrap: wrap;
  gap: var(--spacing-unit);
  color: var(--text-secondary);
