  display: -webkit-box;
  overflow: hidden;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}
#big-picture .souvenir-lightbox__other-count {
  flex-shrink: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text-secondary);
  cursor: help;
  font-size: 14px;
  font-weight: 500;
  font-family: inherit;
}
#big-picture .souvenir-lightbox__other-count:focus-visible, #big-picture .souvenir-lightbox__other-count[data-focus-visible=true] {
  border-radius: 2px;
  outline: 1px solid var(--primary);
  outline-offset: 2px;
}
#big-picture .souvenir-lightbox__achievement-tooltip {
  box-sizing: border-box;
  width: min(460px, 100vw - 160px);
  min-width: 0;
  max-width: min(460px, 100vw - 160px);
  max-height: min(340px, 100vh - 96px);
  align-items: stretch;
  justify-content: flex-start;
  padding: calc(var(--spacing-unit) * 2);
  overflow: hidden;
  border: 1px solid var(--border);
  white-space: normal;
  pointer-events: auto;
}
#big-picture .souvenir-lightbox__achievement-list {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing-unit) / 2);
  width: 100%;
  min-width: 0;
  max-height: min(308px, 100vh - 128px);
  margin: 0;
  padding: 0 calc(var(--spacing-unit) / 2) 0 0;
  overflow-x: hidden;
  overflow-y: auto;
  list-style: none;
}
#big-picture .souvenir-lightbox__achievement-list-item {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--spacing-unit);
  min-height: 38px;
  overflow: hidden;
}
#big-picture .souvenir-lightbox__achievement-list-icon {
  position: relative;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  overflow: hidden;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
}
#big-picture .souvenir-lightbox__achievement-list-icon img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
#big-picture .souvenir-lightbox__achievement-list-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
}
#big-picture .souvenir-lightbox__achievement-list-copy strong,
#big-picture .souvenir-lightbox__achievement-list-copy small {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
#big-picture .souvenir-lightbox__achievement-list-copy strong {
  color: var(--text);
  font-size: 14px;
}
#big-picture .souvenir-lightbox__achievement-list-copy small {
  color: var(--text-secondary);
  font-size: 12px;
}
#big-picture .souvenir-lightbox__meta {
  flex-wrap: wrap;
  gap: var(--spacing-unit);
  color: var(--text-secondary);
  font-size: 14px;
}
#big-picture .souvenir-lightbox__meta-separator {
  width: 4px;
  height: 4px;
  flex-shrink: 0;
  border-radius: 50%;
  background: var(--text-secondary);
  opacity: 0.7;
}
#big-picture .souvenir-lightbox__unlock-time {
  opacity: 0.65;
}
#big-picture .souvenir-lightbox__game {
  gap: var(--spacing-unit);
}
#big-picture .souvenir-lightbox__game-icon {
  position: relative;
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  overflow: hidden;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-secondary);
}
#big-picture .souvenir-lightbox__game-icon img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
#big-picture .souvenir-lightbox__rarity {
  flex-shrink: 0;
  gap: calc(var(--spacing-unit) / 2);
  padding: calc(var(--spacing-unit) * 0.75) var(--spacing-unit);
  border: 1px solid transparent;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
}
#big-picture .souvenir-lightbox__rarity--rare {
  border-color: rgba(244, 165, 16, 0.65);
  background: rgba(48, 32, 4, 0.88);
  color: #ffd36d;
}
#big-picture .souvenir-lightbox__rarity--platinum {
  border-color: rgba(12, 241, 202, 0.7);
  background: linear-gradient(105deg, transparent 70%, rgba(255, 255, 255, 0.15) 85%, transparent 100%), linear-gradient(120deg, #30edc5 0%, #16b195 100%);
  color: #052d26;
}
#big-picture .souvenir-lightbox__actions {
  flex-shrink: 0;
  justify-content: flex-end;
  gap: var(--spacing-unit);
}
#big-picture .souvenir-lightbox__actions .button__icon-container::before,
#big-picture .souvenir-lightbox__actions .button__icon-container::after {
  display: none;
}
#big-picture .souvenir-lightbox__action--pending.button--disabled {
  opacity: 1;
}
@media (max-width: 1100px) {
  #big-picture .souvenir-lightbox__info {
    align-items: stretch;
    flex-direction: column;
  }
  #big-picture .souvenir-lightbox__actions {
    justify-content: flex-start;
    flex-wrap: wrap;
  }
}#big-picture .big-picture-souvenir-report-modal {
  width: min(560px, 100vw - 64px);
}
#big-picture .big-picture-souvenir-report-modal__backdrop {
  z-index: 130;
}
#big-picture .big-picture-souvenir-report-modal__form {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing-unit) * 4);
}
#big-picture .big-picture-souvenir-report-modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: calc(var(--spacing-unit) * 2);
  margin-top: calc(var(--spacing-unit) * 2);
}




